// src/lib/api-client.ts
// HTTP client for external API services
// The actual API runs in a separate service - optimize how you use these calls!

const API_BASE = process.env.EXTERNAL_API_URL || 'http://localhost:3001';

// Simple request caching with 5-minute TTL
type CacheEntry<T> = {
  data: T;
  timestamp: number;
};

const cache = new Map<string, CacheEntry<any>>();
const pendingRequests = new Map<string, Promise<any>>();
const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

function getCacheKey(method: string, url: string, body?: string): string {
  return `${method}:${url}${body ? `:${body}` : ''}`;
}

function isCacheValid(entry: CacheEntry<any>): boolean {
  return Date.now() - entry.timestamp < CACHE_TTL;
}

async function cachedFetch<T>(method: string, url: string, options?: RequestInit): Promise<T> {
  const cacheKey = getCacheKey(method, url, options?.body as string);

  // Return cached data if valid
  const cached = cache.get(cacheKey);
  if (cached && isCacheValid(cached)) {
    return cached.data;
  }

  // Return pending request if already in flight (deduplication)
  if (pendingRequests.has(cacheKey)) {
    return pendingRequests.get(cacheKey)!;
  }

  // Make the request
  const requestPromise = (async () => {
    const res = await fetch(url, { method, ...options });
    if (!res.ok) throw new Error(`Failed to fetch ${url}`);
    const data = await res.json();

    // Cache the result
    cache.set(cacheKey, {
      data,
      timestamp: Date.now(),
    });

    return data;
  })();

  // Store pending request to deduplicate simultaneous requests
  pendingRequests.set(cacheKey, requestPromise);

  try {
    return await requestPromise;
  } finally {
    pendingRequests.delete(cacheKey);
  }
}

export async function fetchUserFromService() {
  return cachedFetch(`${API_BASE}/api/user`);
}

export async function fetchProductsFromService() {
  return cachedFetch(`${API_BASE}/api/products`);
}

export async function fetchReviewsFromService() {
  return cachedFetch(`${API_BASE}/api/reviews`);
}

export async function fetchConfigFromService() {
  return cachedFetch(`${API_BASE}/api/config`);
}

export async function fetchProfileFromService(userId: string) {
  return cachedFetch(`${API_BASE}/api/profile/${userId}`);
}

export async function logAnalyticsToService(data: unknown) {
  // Fire-and-forget: don't wait for response and don't cache
  fetch(`${API_BASE}/api/analytics`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(data),
  }).catch(() => {
    // Silently ignore analytics errors
  });
}

